## Submitted testbench
```systemverilog
module tb;
  // Clock generation (period = 8 time units)
  logic clk;
  initial begin
    clk = 1'b0;
    forever #(8/2) clk = ~clk;
  end

  // Control and stimulus signals
  logic rst;
  logic [15:0] prescale_val;
  logic rxd;
  logic [15:0] s_axis_tdata;
  logic s_axis_tvalid;
  logic [1:0]  m_axis_tready_int;
  logic        m_axis_tvalid;
  logic [7:0]  m_axis_tdata;
  // Dummy connections for un-used outputs of the DUT
  logic dummy_s_axis_tready;
  logic dummy_txd;
  logic dummy_tx_busy;
  logic dummy_rx_busy;
  logic dummy_rx_overrun_error;
  logic dummy_rx_frame_error;

  // DUT instantiation
  uart #(.DATA_WIDTH(8)) dut (
    .clk          (clk),
    .rst          (rst),
    .s_axis_tdata (s_axis_tdata),
    .s_axis_tvalid(s_axis_tvalid),
    .s_axis_tready(dummy_s_axis_tready),
    .m_axis_tdata (m_axis_tdata),
    .m_axis_tvalid(m_axis_tvalid),
    .m_axis_tready(m_axis_tready_int),
    .rxd          (rxd),
    .txd          (dummy_txd),
    .tx_busy      (dummy_tx_busy),
    .rx_busy      (dummy_rx_busy),
    .rx_overrun_error(dummy_rx_overrun_error),
    .rx_frame_error(dummy_rx_frame_error),
    .prescale     (prescale_val)
  );

  // Simple wait‑for‑n‑cycles task
  task automatic wait_ncycles(input int n);
    repeat (n) @(negedge clk);
  endtask

  // Task to transmit a byte on rxd (LSB‑first)
  task automatic uart_send_byte(input byte unsigned b);
    // start bit
    rxd = 1'b0;
    #(prescale_val*8);
    // data bits
    for (int i=0; i<8; i++) begin
      rxd = (b >> i) & 1'b1;
      #(prescale_val*8);
    end
    // stop bit
    rxd = 1'b1;
    #(prescale_val*8);
  endtask

  initial begin
    // Initialize all control signals
    prescale_val = 16'd5;
    rst = 1'b0;
    rxd = 1'b1;
    s_axis_tdata = 16'd0;
    s_axis_tvalid = 1'b0;

    // Reset pulse
    #10 rst = 1'b1;
    #20 rst = 1'b0;

    // First frame (any data, e.g., 8'hA5)
    uart_send_byte(8'hA5);

    // Wait until the receiver asserts m_axis_tvalid (word ready)
    @(posedge m_axis_tvalid);

    // Keep the sink stalled (m_axis_tready low)

    // Second frame carrying the target word 8'hC3
    uart_send_byte(8'hC3);

    // Wait until the receiver asserts m_axis_tvalid again (new word ready)
    @(posedge m_axis_tvalid);
    // Complete the handshake
    #1 m_axis_tready_int = 1'b1;
    #1 m_axis_tready_int = 1'b0;

    // Allow a few cycles for any coverage checks to settle
    repeat (50) @(negedge clk);

    $finish;
  end
endmodule
```

